      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Int<CO>{}, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CO>{}, K),
      make_stride((int64_t)K, Int<1>{})
  );

  // Stage the (small) filter bank into shared memory as fp32
  extern __shared__ float sW_raw[];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CO>{}, K),
      make_stride(K, Int<1>{})
  );

  for (int idx = tid; idx < CO * K; idx += Threads) {
    int oc = idx / K;
    int t  = idx - oc * K;
    sW(oc, t) = (float)mW(oc, t);
  }
  __syncthreads();

  // Map this thread's pixels (coalesced along width)
  int  oh_arr[PVec];
  int  ow_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    valid[i] = (p < P_total);
    if (valid[i]) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Register accumulators
  float acc[CO][PVec];
  #pragma unroll
  for (int oc = 0; oc < CO; ++oc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc][i] = 0.0f;
    }
  }

  // Loop over the K = Cin*KH*KW taps
  for (int t = 0; t < K; ++t) {
    int kw = t % KW;
    int r  = t / KW;
    int kh = r % KH;
    int ic = r / KH;

    // Fetch input values for this tap (cached, coalesced across threads)
    float xv[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      xv[i] = 0.0f;
      if (valid[i]) {
        int ih = oh_arr[i] * stride - pad + kh;
        int iw = ow_arr[i] * stride - pad + kw;
        if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          xv[i] = (float)mX(ic, ih, iw);
        }
      }
    }

    // Rank-1 update across all output channels
    #pragma unroll
    for (int oc = 0; oc < CO; ++oc) {
      float wv = sW(oc, t);
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        acc[oc][i] += xv[i] * wv;
      }
    }
  }

  // Epilogue: store results
  #pragma unroll
  for (int oc = 0; oc < CO; ++oc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (valid[i]) {
        mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[oc][i]);
      }
    }
  }
