// Cooperative tiled Conv2d forward kernel (bf16 in/out, fp32 accumulation).
// Each block computes a tile of PTile = Threads*PVec output pixels (one image)
// for ALL Cout output channels. Weights (Cout x Cin*KH*KW) are staged into
// shared memory once per block; each thread accumulates Cout x PVec partial
// sums in registers and iterates over the K = Cin*KH*KW taps.
template <typename T, int CO>
__global__ void conv2d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int KH, int KW,
    int stride, int pad,
    int Hout, int Wout)
{
  constexpr int Threads = 256;
  constexpr int PVec    = 2;
  constexpr int PTile   = Threads * PVec;

  const int tid     = threadIdx.x;
  const int n       = blockIdx.y;
  const int p_block = blockIdx.x * PTile;

  const int P_total = Hout * Wout;
  const int K       = Cin * KH * KW;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sYn = (int64_t)CO * Hout * Wout;

  // Global tensors (per-image views) via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride((int64_t)H * Win, (int64_t)Win, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Int<CO>{}, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CO>{}, K),
      make_stride((int64_t)K, Int<1>{})
  );

  // Stage the (small) filter bank into shared memory as fp32
  extern __shared__ float sW_raw[];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CO>{}, K),
      make_stride(K, Int<1>{})
  );

  for (int idx = tid; idx < CO * K; idx += Threads) {
    int oc = idx / K;
    int t  = idx - oc * K;
    sW(oc, t) = (float)mW(oc, t);
  }
  __syncthreads();

  // Map this thread's pixels (coalesced along width)
  int  oh_arr[PVec];
  int  ow_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    valid[i] = (p < P_total);
    if (valid[i]) {
      int oh = p / Wout;
      int ow = p - oh * Wout;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  // Register accumulators
  float acc[CO][PVec];
  #pragma unroll
  for (int oc = 0; oc < CO; ++oc) {
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc][i] = 0.0f;
    }
  }

  // Loop over the K = Cin*KH*KW taps
  for (int t = 0; t < K; ++t) {
    int kw = t % KW;
    int r  = t / KW;
    int kh = r % KH;
    int ic = r / KH;

    // Fetch input values for this tap (cached, coalesced across threads)
    float xv[PVec];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      xv[i] = 0.0f;
      if (valid[i]) {
